import{_ as t,o,c as a,a5 as n}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"Video auto-edit agent","description":"","frontmatter":{},"headers":[],"relativePath":"feature/video-auto-edit-agent/spec.md","filePath":"feature/video-auto-edit-agent/spec.md"}'),s={name:"feature/video-auto-edit-agent/spec.md"};function i(r,e,c,d,l,u){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="video-auto-edit-agent" tabindex="-1">Video auto-edit agent <a class="header-anchor" href="#video-auto-edit-agent" aria-label="Permalink to &quot;Video auto-edit agent&quot;">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>Replace the server auto-edit&#39;s single Claude call with a Claude tool-use agent loop, so a user&#39;s instruction plus uploaded clips produce an edit closer to the DemoVideo agent workflow: look at footage, find clean shots and beats, build a plan, fix its own validation errors, and return both an <strong>editable Video Space timeline</strong> and, when asked, an <strong>MP4</strong>.</p><p>Decisions (user, 2026-11-10): model <strong>Claude Sonnet 5.5</strong> (<code>claude-sonnet-5-5</code>); output <strong>timeline and optional MP4</strong> (user chooses per run).</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>In: the existing <code>plan</code> job of <code>server_video_edit</code> (ai-service), the auto-edit admission/receipt in business-service, and the Video Space server-edit panel. Out (later phases): reference-video style analysis, durable per-user correction memory, EditAtlas inside the agent (the in-editor planner already uses it), new paid footage generation.</p><h2 id="observable-acceptance" tabindex="-1">Observable acceptance <a class="header-anchor" href="#observable-acceptance" aria-label="Permalink to &quot;Observable acceptance&quot;">​</a></h2><ol><li>User imports clips (+ optional music/voice), writes an instruction, ticks or unticks &quot;Xuất MP4&quot;, and starts an auto edit. Browser may close; the job continues on the server.</li><li>The agent inspects footage through tools (frames, scene cuts, beats, transcript) before submitting a plan. The plan is validated by the existing <code>validate_plan</code>; validation errors go back to the agent as a tool error so it can correct them, up to the turn limit.</li><li>When the plan is accepted, the panel offers <strong>&quot;Mở trên timeline&quot;</strong>: it adds the plan as a <strong>new scene</strong> in the current project (never overwrites the user&#39;s scene), in one undo step. Clips, trims, speed, text (with font/colour/position), transitions, music/voice layers map to native layers. Plan features with no native equivalent (blur fit, circle/arrow callouts, portrait glow, freeze) are listed in the summary as &quot;MP4 only&quot;.</li><li>If &quot;Xuất MP4&quot; was ticked, the existing render job runs from the same accepted plan and the MP4 downloads as today. Unticked, the job ends after the plan with no render cost.</li><li>The panel shows stages: analyzing, agent working (turn n / max), rendering, QC, uploading, completed, failed. Failures show a short reason; originals are untouched.</li><li>The existing 8-action chat assistant and its behaviour stay unchanged.</li></ol><h2 id="agent-contract" tabindex="-1">Agent contract <a class="header-anchor" href="#agent-contract" aria-label="Permalink to &quot;Agent contract&quot;">​</a></h2><ul><li>Surface: Claude API Messages with user-defined tools, <strong>manual loop</strong> in ai-service using the official <code>anthropic</code> SDK (already pinned 2.3.0). Manual loop because each turn must pass the worker&#39;s cancel/lease check and update the durable job stage.</li><li>Model <code>claude-sonnet-5-5</code>, adaptive thinking, <code>output_config.effort</code> <code>medium</code> (configurable), <code>fallbacks: &quot;default&quot;</code> with beta <code>server-side-fallback-2026-07-01</code>. Handle <code>stop_reason</code> <code>refusal</code> / <code>max_tokens</code> explicitly. No forced <code>tool_choice</code> (400 on this model): <code>auto</code> + prompt instruction.</li><li>Tools (all read-only except <code>submit_plan</code>; none run model-supplied commands, filters, paths or URLs): <ul><li><code>list_sources()</code> → verified probes (kind, role, duration, size, has_audio), transcripts, beat estimates, SFX names.</li><li><code>view_frames(asset_id, seconds[])</code> → one contact-sheet JPEG (≤6 frames, ≤1024 px wide) with timestamps burned in. Budget ≤60 frames per job.</li><li><code>detect_scenes(asset_id)</code> → scene-cut times from ffmpeg scene detection, cached per asset.</li><li><code>submit_plan(summary, plan)</code> → runs <code>RenderPlan</code> parse + <code>validate_plan</code>; returns accepted, or <code>is_error</code> with the validation message.</li></ul></li><li>Loop ends when <code>submit_plan</code> is accepted and the model ends its turn. Limits: ≤16 model turns, ≤600 s wall clock (shared job deadline), ≤60 frames, ≤64k output tokens per job; exceeding one fails the job with a specific code.</li><li>Prompt caching: frozen system prompt (runtime guide + genre text + schema) and tool list first, <code>cache_control</code> on the last system block; history append-only.</li><li>Durable fence unchanged: <code>provider_started</code> is saved before the first model call; a crash or unknown outcome after that becomes <code>RECONCILIATION_REQUIRED</code>, never an automatic re-run. Usage (input/output/cache tokens, turns, frames) is recorded on the job receipt for credit review.</li></ul><h2 id="api-changes" tabindex="-1">API changes <a class="header-anchor" href="#api-changes" aria-label="Permalink to &quot;API changes&quot;">​</a></h2><ul><li><code>POST /api/v1/workspaces/{ws}/video-projects/{project}/auto-edits</code> body gains optional <code>render_mp4</code> (boolean, default <code>true</code> to keep current behaviour).</li><li><code>GET .../auto-edits/{job}</code> adds <code>summary</code>, <code>plan</code> (accepted RenderPlan), <code>agent</code> <code>{turns, frames}</code> and <code>render_mp4</code>. No storage keys, prompts or provider payloads.</li><li>Internal plan receipt gains <code>agent</code> usage; <code>kind=plan</code> envelope gains nothing else.</li></ul><h2 id="security-and-cost" tabindex="-1">Security and cost <a class="header-anchor" href="#security-and-cost" aria-label="Permalink to &quot;Security and cost&quot;">​</a></h2><p>Instruction, captions and transcripts are untrusted data. Source bytes, keys and URLs never enter the prompt; only sampled frames, probes and transcripts. Credits: the plan step is charged once per job as now; the price must be reviewed after measuring real usage (estimate, unmeasured: 100–200k input + ~10k output tokens per job on Sonnet 5.5).</p>',14)])])}const m=t(s,[["render",i]]);export{h as __pageData,m as default};
